import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { useCart } from '../context/ShopPage'; // Adjust the import path as necessary

const Makepayment = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { product } = location.state || {};
  const { cartItems, totalPrice, clearCart } = useCart();

  const [phone, setPhone] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const amountToPay = product ? parseFloat(product.product_cost) : totalPrice;

  const payNow = async (e) => {
    e.preventDefault();
    if (!phone || phone.length < 10) {
      setError('Please enter a valid phone number.');
      return;
    }

    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const response = await axios.post('https://sengi2025.pythonanywhere.com/api/mpesa_payment ', {
        amount: amountToPay,
        phone: phone,
      });

      setLoading(false);
      setSuccess(response.data.message || 'Payment initiated successfully!');
      setPhone('');

      if (!product) {
        clearCart();
      }

      setTimeout(() => {
        navigate('/checkout');
      }, 3000);

    } catch (err) {
      setLoading(false);
      setError('Payment failed. Please try again later.');
      console.error(err);
    }
  };

  if (!product && cartItems.length === 0) {
    return (
      <div className="text-center p-5">
        <h2 className="text-danger">Your cart is empty.</h2>
        <button onClick={() => navigate('/')} className="btn btn-primary mt-3">
          Go to Products
        </button>
      </div>
    );
  }

  return (
    <div className="row mt-4 p-3">
      <div className="col-md-6">
        <div className="card shadow-sm">
          <div className="card-body">
            {product ? (
              <>
                <img
                  src={`https://andera.pythonanywhere.com/static/images/ ${product.product_photo}`}
                  alt={product.product_name}
                  className="img-fluid rounded mb-3"
                />
                <h3 className="text-info">{product.product_name}</h3>
                <p className="text-muted">{product.product_description}</p>
              </>
            ) : (
              <>
                <h4 className="text-info mb-3">Cart Summary</h4>
                {cartItems.map((item, index) => (
                  <div key={index} className="mb-2 border-bottom pb-2">
                    <p className="mb-1">
                      <b>{item.product_name}</b> (x{item.quantity})
                    </p>
                    <p className="text-muted">
                      KES {(item.product_cost * item.quantity).toFixed(2)}
                    </p>
                  </div>
                ))}
              </>
            )}
          </div>
        </div>
      </div>

      <div className="col-md-6">
        <h1 className="text-danger">KES {amountToPay.toFixed(2)}</h1>
        <h5 className="text-success">LIPA NA M-PESA</h5>

        <form onSubmit={payNow} className="card shadow-sm p-4 mt-3">
          {loading && <p className="text-primary">Processing payment...</p>}
          {success && <p className="text-success">{success}</p>}
          {error && <p className="text-danger">{error}</p>}

          <input
            type="number"
            value={amountToPay}
            readOnly
            className="form-control mb-3"
            placeholder="Amount to Pay"
          />

          <input
            type="tel"
            placeholder="Enter phone (e.g., 2547XXXXXXX)"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            className="form-control mb-3"
            required
          />

          <button type="submit" className="btn btn-success w-100">
            <b>Pay Now</b>
          </button>
        </form>
      </div>
    </div>
  );
};

export default Makepayment;
